#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5

banner "Ajer Haus backend infra setup"

# ── Stage 1: Neon — isolated schema + role inside Unstitch's project ──────
stage "Neon: dedicated schema + role"
say "Ajer Haus's tables live in their own Postgres schema (ajer_haus), not"
say "Unstitch's (public) — inside the SAME Neon project, behind a role that"
say "can only see that one schema. This keeps 'shared database' true while"
say "making it physically impossible for a leaked connection string or a"
say "buggy query to reach Unstitch's orders/payments."
open_url "https://console.neon.tech"
step "Open the Neon project that backs Unstitch, then open its SQL Editor."
note "Pick a strong password for the new role below before you run the SQL —"
note "you'll paste it into the connection string in a moment, not here."
say ""
say "Paste and run this in the SQL Editor (replace CHANGE_ME_PASSWORD first):"
say ""
say "  CREATE SCHEMA IF NOT EXISTS ajer_haus;"
say "  CREATE ROLE ajer_haus_app WITH LOGIN PASSWORD 'CHANGE_ME_PASSWORD';"
say "  GRANT USAGE, CREATE ON SCHEMA ajer_haus TO ajer_haus_app;"
say "  ALTER DEFAULT PRIVILEGES IN SCHEMA ajer_haus GRANT ALL ON TABLES TO ajer_haus_app;"
say "  ALTER DEFAULT PRIVILEGES IN SCHEMA ajer_haus GRANT ALL ON SEQUENCES TO ajer_haus_app;"
say "  ALTER ROLE ajer_haus_app SET search_path = ajer_haus;"
say ""
note "The search_path line matters: without it, ajer_haus_app's queries"
note "default to Postgres's 'public' schema, where it has no grants at all."
pause "Run that SQL now, then press Enter."
step "Go to the project's Dashboard -> Connection Details."
step "Switch the role dropdown to ajer_haus_app, and database to the one you just used."
step "Make sure 'Pooled connection' is ON, then copy the full connection string."
note "It looks like: postgresql://ajer_haus_app:PASSWORD@ep-...-pooler.../neondb?sslmode=require"
ask_secret DATABASE_URL "Paste the ajer_haus_app pooled connection string:"
write_env DATABASE_URL "$DATABASE_URL"
set_secret DATABASE_URL "$DATABASE_URL"

# ── Stage 2: Stripe — a separate account for this separate business ───────
stage "Stripe: a separate account for Ajer Haus"
say "Unstitch and Ajer Haus are separate businesses, so this needs its own"
say "Stripe account (its own bank account/payouts), not a second key under"
say "Unstitch's. If Ajer Haus doesn't have a Stripe account yet, create one"
say "now; if it does, just sign in to it."
open_url "https://dashboard.stripe.com/register"
step "Create (or sign into) the Ajer Haus Stripe account."
step "Make sure you're in TEST mode (toggle, top right) for now."
open_url "https://dashboard.stripe.com/test/apikeys"
step "Click 'Reveal test key' on the Secret key row, then copy it (sk_test_...)."
ask_secret STRIPE_SECRET_KEY "Paste the Stripe test Secret key:"
write_env STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
set_secret STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
note "STRIPE_WEBHOOK_SECRET isn't ready yet — Stripe only issues one once"
note "there's a real deployed URL for the webhook endpoint to point at."
note "That's a short follow-up after Stage 5, once Vercel gives you a URL."
SKIPPED+=("STRIPE_WEBHOOK_SECRET — create the webhook endpoint at https://dashboard.stripe.com/test/webhooks once deployed, pointed at <your-vercel-url>/api/stripe-webhook, then add its signing secret to Vercel")

# ── Stage 3: Resend — transactional email ──────────────────────────────────
stage "Resend: order confirmation + notify-me emails"
say "This sends the order confirmation and 'notify me' emails (src/lib/emailTemplate.ts)."
open_url "https://resend.com/api-keys"
step "Create (or reuse) an API key with send access."
ask_secret RESEND_API_KEY "Paste the Resend API key:"
write_env RESEND_API_KEY "$RESEND_API_KEY"
set_secret RESEND_API_KEY "$RESEND_API_KEY"
open_url "https://resend.com/domains"
step "If hello@ajerhaus.com's domain isn't verified yet, add + verify it here."
note "Until it's verified, Resend will reject sends from that address — the"
note "code logs a warning and moves on rather than failing the request."

# ── Stage 4: Admin password + session secret ───────────────────────────────
stage "Admin login secrets"
say "/admin is gated by one shared password (ADMIN_PASSWORD) plus a signed"
say "session cookie (SESSION_SECRET) — unrelated to Unstitch's admin login."
ask_secret ADMIN_PASSWORD "Choose a long, random admin password (not 'password123'):"
write_env ADMIN_PASSWORD "$ADMIN_PASSWORD"
set_secret ADMIN_PASSWORD "$ADMIN_PASSWORD"
if command -v openssl >/dev/null 2>&1; then
  SESSION_SECRET=$(openssl rand -hex 32)
  write_env SESSION_SECRET "$SESSION_SECRET"
  set_secret SESSION_SECRET "$SESSION_SECRET"
  say ""
  warn "This is the only time this is shown — SESSION_SECRET: $SESSION_SECRET"
  note "(Already saved to $ENV_FILE and, if gh is set up, to a GitHub secret.)"
  pause "Copy it somewhere safe if you need it outside this machine, then press Enter."
else
  warn "openssl isn't available here — generate 64 hex chars yourself (e.g. on"
  warn "another machine: openssl rand -hex 32) and paste it in."
  ask_secret SESSION_SECRET "Paste a 64-character hex secret:"
  write_env SESSION_SECRET "$SESSION_SECRET"
  set_secret SESSION_SECRET "$SESSION_SECRET"
fi

# ── Stage 5: Vercel — a new, separate project ───────────────────────────────
stage "Vercel: new project + env vars"
say "Ajer Haus gets its OWN Vercel project (distinct from Unstitch's) so a"
say "deploy of one site never touches the other, and each stays well under"
say "the Hobby plan's 12-Serverless-Function cap on its own."
open_url "https://vercel.com/new"
step "Import the ajer-haus repo as a new project (do not add it to Unstitch's)."
step "Before the first deploy, open Settings -> Environment Variables and add:"
note "  DATABASE_URL, STRIPE_SECRET_KEY, RESEND_API_KEY, ADMIN_PASSWORD, SESSION_SECRET"
note "  — the exact values are already sitting in $ENV_FILE on this machine."
pause "Add those five, then deploy. Press Enter once it's live."
ask VERCEL_URL "Paste the deployed URL (e.g. https://ajer-haus.vercel.app or your custom domain):"
write_env PUBLIC_SITE_URL "$VERCEL_URL"
open_url "https://dashboard.stripe.com/test/webhooks"
step "Add an endpoint: ${VERCEL_URL}/api/stripe-webhook"
step "Select events: checkout.session.completed, checkout.session.expired."
step "Click into the new endpoint and reveal its Signing secret (whsec_...)."
ask_secret STRIPE_WEBHOOK_SECRET "Paste the webhook signing secret:"
write_env STRIPE_WEBHOOK_SECRET "$STRIPE_WEBHOOK_SECRET"
set_secret STRIPE_WEBHOOK_SECRET "$STRIPE_WEBHOOK_SECRET"
warn "Add PUBLIC_SITE_URL and STRIPE_WEBHOOK_SECRET to the Vercel project's"
warn "env vars too (same two values just written to $ENV_FILE), then redeploy."
SKIPPED+=("Add PUBLIC_SITE_URL + STRIPE_WEBHOOK_SECRET to the Vercel project and redeploy")

finish
}

run_wizard "$@"; exit
